[ -n "$HC_TERMINAL_ID" ] && j=$(tr -d '\n') && f="${XDG_STATE_HOME:-$HOME/.local/state}/herdr/terminal-sessions.jsonl" && mkdir -p "${f%/*}" && printf '{"terminal":"%s","agent":"claude","session_id":"%s","cwd":"%s","at":%s}\n' "$HC_TERMINAL_ID" "$(printf %s "$j" | sed -nE 's/.*"session_id" *: *"([^"]*)".*/\1/p')" "$(printf %s "$j" | sed -nE 's/.*"cwd" *: *"(([^"\\]|\\.)*)".*/\1/p')" "$(date +%s)" >> "$f"; exit 0
